import{_ as o,o as a,i as t,a9 as n}from"./chunks/framework.DuwpaNh0.js";const h=JSON.parse('{"title":"Conductor Module Interface Design","description":"","frontmatter":{"title":"Conductor Module Interface Design"},"headers":[],"relativePath":"modules/5-advanced/conductor-interop/conductor-interop.md","filePath":"modules/5-advanced/conductor-interop/conductor-interop.md","lastUpdated":1785736994000}'),r={name:"modules/5-advanced/conductor-interop/conductor-interop.md"};function s(i,e,c,l,d,u){return a(),t("div",null,e[0]||(e[0]=[n('<h1 id="conductor-module-interface-design" tabindex="-1">Conductor Module Interface Design <a class="header-anchor" href="#conductor-module-interface-design" aria-label="Permalink to &quot;Conductor Module Interface Design&quot;">​</a></h1><p>This section records <em>why</em> the Conductor module interface (the <code>IDataHandler</code>/<code>TypedValue&lt;DataType&gt;</code> protocol between an evaluator and a module) is shaped the way it is - as distinct from the <a href="./../../2-bundle/4-conventions/">Bundle Conventions</a> section, which covers <em>how</em> to actually write bundle code against it.</p><p>Most of these decisions came out of a design discussion between Martin Henz and the py-slang team while fixing <a href="https://github.com/source-academy/py-slang/pull/307" target="_blank" rel="noreferrer">py-slang#307</a>. The short version, if you only read one line: <strong>keep it simple on the module side</strong>. A module should never have to think about integers vs floats, or pairs vs arrays, as distinct concepts - the evaluator (py-slang, js-slang, ...) is responsible for presenting a clean, minimal interface, and a module just consumes it.</p><ul><li><a href="./1-numbers.html">Numbers are always floats</a></li><li><a href="./2-pairs-and-arrays.html">Pairs and arrays are the same thing</a></li><li><a href="./3-opaque.html"><code>DataType.OPAQUE</code>: where recursion stops</a></li><li><a href="./4-binary-tree-exception.html">The <code>binary_tree</code> exception</a></li><li><a href="./5-closure-call-sync.html"><code>closure_call_sync</code>: an optional fast path for hot callback loops</a></li></ul>',4)]))}const m=o(r,[["render",s]]);export{h as __pageData,m as default};
